"""Finding the stretches of opening hours nobody covers."""

from typing import Iterable, List
from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans

def _check_inside(worked, opening):
    for span in worked:
        if span.start < opening.start or span.end > opening.end:
            raise ValueError(
                f"{format_span(span)} is outside opening hours"
            )

def _uncovered(merged, opening):
    edges = [(opening.start, opening.start)]
    edges += [(span.start, span.end) for span in merged]
    edges.append((opening.end, opening.end))
    return [
        Span(left[1], right[0])
        for left, right in zip(edges, edges[1:])
        if left[1] < right[0]
    ]

def _label(gap):
    return f"gap {format_span(gap)} ({gap.minutes} min)"

# ---
def find_gaps(worked: Iterable[Span], opening: Span) -> List[str]:
    """One label per uncovered stretch of opening hours."""
    worked = list(worked)
    _check_inside(worked, opening)
    merged = merge_spans(worked)
    return [_label(gap) for gap in _uncovered(merged, opening)]

